import { Editor } from '@devexpress/analytics-core/analytics-widgets';
import { SeriesPointModel } from '../components/series/_point';
import { createViewModelGenerator } from '@devexpress/analytics-core/analytics-serializer-native';
import { koUtils } from '@devexpress/analytics-core/analytics-internal-native';
export class PointsEditor extends Editor {
    createViewModel() {
        return createViewModelGenerator(super.createViewModel())
            .generateProperty('addPoint', () => this.addPoint())
            .getViewModel();
    }
    constructor(info, level, parentDisabled, textToSearch) {
        super(info, level, parentDisabled, textToSearch);
    }
    addPoint() {
        const unwrapped = koUtils.unwrap(this._model);
        const series = unwrapped['owner'] || unwrapped;
        return SeriesPointModel.createNew(series);
    }
}
